// Frame math for the pixelfx sprite sheets in assets/fx (generated by scripts/fx-sheets.mjs).
// Every frame has the same size and duration, so a frame is just elapsed time * fps.
// The functions are worklets because the player calls them on the UI thread.

export interface PixelFxSheet {
  fps: number;
  loop: boolean;
  frames: number;
  frameSize: [number, number];
  columns: number;
}

export function frameAt(elapsedMs: number, sheet: PixelFxSheet): number {
  'worklet';
  const i = Math.floor((Math.max(0, elapsedMs) * sheet.fps) / 1000);
  return sheet.loop ? i % sheet.frames : Math.min(i, sheet.frames - 1);
}

export function isFinished(elapsedMs: number, sheet: PixelFxSheet): boolean {
  'worklet';
  return !sheet.loop && elapsedMs >= (sheet.frames * 1000) / sheet.fps;
}

export function frameRect(index: number, sheet: PixelFxSheet) {
  'worklet';
  const [width, height] = sheet.frameSize;
  return {
    x: (index % sheet.columns) * width,
    y: Math.floor(index / sheet.columns) * height,
    width,
    height,
  };
}
